&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Principal Product Manager (AI Product)&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; - Join Our Innovative Team at thinkcell Software&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Our Story&lt;/span&gt;&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At thinkcell, we create powerful software solutions that help professionals be more efficient and productive. Founded in 2002 and based in Berlin, our tools integrate seamlessly with Microsoft Office to help users create presentations, charts, and diagrams with ease. Our dynamic, international team values creativity, collaboration, and technical excellence.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What You Will Do&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;TextRun SCXW223456913 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;You&#39;ll&lt;/span&gt; &lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;co-&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;own our AI product end-to-end, from discovery to &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;business outcome&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;. &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;You&#39;ll&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt; set direction&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;s to&lt;/span&gt; &lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;p&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;roduct &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;m&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;anagers who each own parts of the product, while staying close to customers and &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;internal stakeholders&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;. &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;With&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt; designers and engineers, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;you&#39;ll&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt; make sure we build the right thing&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;s and&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt; build them well. This is a pivotal role&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt; to help execute an ambitious vision&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW223456913 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Key Responsibilities:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Co-own the product&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
